// What order does this print? The answer depends on where the
// script starts, and in a fresh module the timer vs immediate
// order is NOT guaranteed — a classic interview trap.
setTimeout(() => console.log('timeout'), 0);
setImmediate(() => console.log('immediate'));
process.nextTick(() => console.log('nextTick'));
Promise.resolve().then(() => console.log('promise'));

// Deterministic parts:
//   nextTick, promise print BEFORE any timer — microtasks drain
//   after the current operation, before the next phase runs.
// Non-deterministic part:
//   timeout vs immediate flips depending on whether the module
//   started inside an I/O callback (then immediate wins).

// Correct mental model: don't order work with 0ms timers.
// Use queueMicrotask for same-loop work and setImmediate for
// 'after I/O' work inside I/O callbacks.

