fullFile.code:
const fs = require('node:fs');

// Inside an I/O callback the order is deterministic:
//   1. microtasks (after each callback)
//   2. setImmediate (check phase of the same iteration)
//   3. setTimeout(1) (timers phase of the NEXT iteration)
fs.readFile(__filename, () => {
  queueMicrotask(() => console.log('1. microtask'));
  setImmediate(() => console.log('2. immediate (check)'));
  setTimeout(() => console.log('3. timer (next timers phase)'), 1);
});

// Key rules to remember:
// - process.nextTick and Promise microtasks drain before the
//   event loop proceeds to the next phase.
// - setImmediate schedules into the check phase of the CURRENT
//   iteration when called from a poll-phase callback.
// - setTimeout(0) is clamped to ~1ms and fires in a LATER
//   timers phase, so it loses to setImmediate inside I/O.
